SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='8458e9e3-a714-5698-b60b-8d26d3100dc8'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('4b7e16e8-46a9-5ab0-9865-01c290a7806e','e87f0745-c706-5cb9-81ed-74e49a1ca5a8')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='8458e9e3-a714-5698-b60b-8d26d3100dc8'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='8458e9e3-a714-5698-b60b-8d26d3100dc8'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('4b7e16e8-46a9-5ab0-9865-01c290a7806e','e87f0745-c706-5cb9-81ed-74e49a1ca5a8')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='8458e9e3-a714-5698-b60b-8d26d3100dc8'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
