  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-13-duplicate-semantic' AND q.fingerprint='e0f51e1940d1988179138d8cccb0c290bbde4f21eac8595f6d60f65ec34c501d'
