  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-13-duplicate-semantic","status":"ok","value":{"customerProfileId":"8458e9e3-a714-5698-b60b-8d26d3100dc8","userId":"72cc2f5b-0c75-51f5-a6f9-aad470712c67","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"4b7e16e8-46a9-5ab0-9865-01c290a7806e","semanticKey":"customer-controls-customer-13-duplicate-semantic","fingerprint":"e0f51e1940d1988179138d8cccb0c290bbde4f21eac8595f6d60f65ec34c501d","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='bb795ccf-a974-556d-a035-54f15003666f' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='627efae6-6061-57bb-ab41-e33c6bb6066f' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"8458e9e3-a714-5698-b60b-8d26d3100dc8"},"prior":null,"committed":{"id":"8458e9e3-a714-5698-b60b-8d26d3100dc8","userId":"72cc2f5b-0c75-51f5-a6f9-aad470712c67","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='8458e9e3-a714-5698-b60b-8d26d3100dc8' AND c.user_id='72cc2f5b-0c75-51f5-a6f9-aad470712c67' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
