   AND ((o.id='0dd443c1-0969-5358-b5e3-5dc795c5702c' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"8458e9e3-a714-5698-b60b-8d26d3100dc8","userId":"72cc2f5b-0c75-51f5-a6f9-aad470712c67","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='1783bcde-1ad6-5638-9d45-f2fab4f4a156' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"72cc2f5b-0c75-51f5-a6f9-aad470712c67","track":"customer","customerProfileId":"8458e9e3-a714-5698-b60b-8d26d3100dc8","sourceCreationRevision":"0","sourceCreationReceipt":"4b7e16e8-46a9-5ab0-9865-01c290a7806e","semanticKey":"customer_buyer_profile/8458e9e3-a714-5698-b60b-8d26d3100dc8/default-free-enrollment/v1"}'::jsonb)))=2));
